<?= $this->extend('layout') ?><?= $this->section('content') ?><p class="intro">A permanent record of completed transactions. All amounts are in Philippine pesos.</p><section class="panel"><div class="table-wrap"><table><thead><tr><th>Sale</th><th>Product</th><th>Customer</th><th>Sold by</th><th>Qty</th><th>Total</th><th>Date</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td>#<?= $r['id'] ?></td><td><b><?= esc($r['product']) ?></b></td><td><?= esc($r['customer']??'Walk-in') ?></td><td><?= esc($r['staff']) ?></td><td><?= $r['quantity'] ?></td><td class="nowrap">₱<?= number_format((float)$r['total_price'],2) ?></td><td class="nowrap"><?= esc($r['created_at']) ?></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="7" class="empty">No transactions yet. Record your first sale to begin.</td></tr><?php endif ?></tbody></table></div><?= $pager->links() ?></section><?= $this->endSection() ?>
